(function(root){
const branches=[['力量',5,3,0,'power','紅蓮之力','攻擊力＋5%'],['體魄',2,5,2,'vitality','戰士體魄','最大生命＋10%'],['烈焰',5,3,1,'mastery','烈焰精通','必殺傷害＋8%'],['終斬',4,3,2,'finale','紅蓮終斬','第三斬額外＋20%'],['戰意',2,4,3,'resolve','浴火戰意','必殺命中兩名不同敵人，完成後減傷15%，持續4秒']];
const nodes=[];
branches.forEach(([name,a,h,d,key,title,effect],branch)=>{
 const remaining={attack:a,hp:h,armor:d},types=[];
 while(types.length<a+h+d)for(const type of ['attack','hp','armor'])if(remaining[type]>0){types.push(type);remaining[type]--}
 types.push('key');types.forEach((type,depth)=>nodes.push({id:`garnet-${branch}-${depth}`,branch,depth,type,key:type==='key'?key:null,title:type==='key'?title:{attack:'攻擊',hp:'生命',armor:'防禦'}[type],effect:type==='key'?effect:{attack:'初始攻擊＋2%',hp:'初始生命＋3%',armor:'護甲減傷＋0.5個百分點'}[type],cost:type==='key'?100:depth<3?10:depth<6?20:30,requires:depth?`garnet-${branch}-${depth-1}`:null}));
});
const key='starwish.growth.v1';
const empty=()=>({version:1,revision:0,shards:0,unlocked:[],firstClears:[]});
function validate(s){if(!s||s.version!==1||!Number.isSafeInteger(s.revision)||s.revision<0||!Number.isSafeInteger(s.shards)||s.shards<0||!Array.isArray(s.unlocked)||new Set(s.unlocked).size!==s.unlocked.length)throw Error('養成資料無法讀取');for(const id of s.unlocked){const node=nodes.find(n=>n.id===id);if(!node||node.requires&&!s.unlocked.includes(node.requires))throw Error('星盤資料無效')}const firstClears=s.firstClears??[];if(!Array.isArray(firstClears)||new Set(firstClears).size!==firstClears.length||firstClears.some(id=>!Number.isInteger(id)||id<1||id>20))throw Error('首通資料無效');return {version:1,revision:s.revision,shards:s.shards,unlocked:[...s.unlocked],firstClears:[...firstClears],...validateIdle(s.idle),...validateStars(s.starboards)}}
function validateStars(stars){if(stars===undefined)return {};if(!stars||typeof stars!=='object'||Array.isArray(stars))throw Error('角色星盤資料無效');for(const [id,unlocked] of Object.entries(stars)){if(!['allen','bruno','liv','finn','luna','flora','sela','leon','sylphie','iris','katia','mila'].includes(id))throw Error('未知角色星盤');validate({...empty(),unlocked})}return {starboards:JSON.parse(JSON.stringify(stars))}}
function forHero(hero){if(hero.id==='garnet')return api;const rarity=hero.rarity,r=rarity==='R',sr=rarity==='SR',keys=hero.id==='katia'?['power','vitality','mastery','poison','pursuit']:hero.id==='mila'?['power','vitality','prayer','rescue','protection']:['power','vitality','defense','mastery','special'];const labels=hero.id==='katia'?['攻擊＋5%','生命＋10%','子彈傷害＋8%','毒傷＋20%','換目標追擊傷害＋20%']:hero.id==='mila'?['攻擊＋5%','生命＋10%','治療＋8%','低生命救援治療＋20%','治療後減傷10%三秒']:[r?'攻擊＋2%':'攻擊＋3%',r?'生命＋4%':'生命＋7%',r?'護甲減傷＋1個百分點':'護甲減傷＋1.5個百分點',r?'普通攻擊傷害＋3%':'必殺傷害＋6%',r?'必殺效果＋4%':({sela:'目標低於40%生命，必殺傷害＋5%',leon:'連鎖第三段傷害＋8%',sylphie:'目標高於70%生命，必殺傷害＋5%',iris:'對已減速目標必殺傷害＋5%'}[hero.id])];
const ownNodes=nodes.map(n=>({...n,key:n.type==='key'?keys[n.branch]:null,title:n.type==='key'?['力量覺醒','生命覺醒','堅守／專精','招式精通','角色特色'][n.branch]:n.title,effect:n.type==='key'?labels[n.branch]:n.type==='attack'?'初始攻擊＋'+(r?'1.4':sr?'1.7':'2')+'%':n.type==='hp'?'初始生命＋'+(r?'2':sr?'2.5':'3')+'%':'護甲減傷＋'+(r?'0.3':sr?'0.4':'0.5')+'個百分點'}));
return {...api,nodes:ownNodes,load(storage){const s=load(storage);return {...s,unlocked:s.starboards?.[hero.id]||[]}},purchase(storage,expected,ids){const full=load(storage),view={...full,unlocked:full.starboards?.[hero.id]||[]};if(JSON.stringify(view)!==JSON.stringify(expected))throw Error('資料已更新，請重新確認');const next=quote(view,ids).next;full.shards=next.shards;full.revision++;full.starboards={...full.starboards,[hero.id]:next.unlocked};storage.setItem(key,JSON.stringify(full));return {...full,unlocked:next.unlocked}},bonuses(state){const b=bonuses(state);b.keys=state.unlocked.map(id=>ownNodes.find(n=>n.id===id)).filter(n=>n.type==='key').map(n=>n.key);return b}}}
function load(storage){const raw=storage.getItem(key);return raw===null?empty():validate(JSON.parse(raw))}
function quote(state,ids){const next=validate(state);let cost=0;for(const id of ids){const n=nodes.find(n=>n.id===id);if(!n||next.unlocked.includes(id)||n.requires&&!next.unlocked.includes(n.requires))throw Error('請先解鎖前置節點');cost+=n.cost;next.unlocked.push(id)}if(!ids.length)throw Error('沒有可培養的節點');if(cost>state.shards)throw Error('星輝碎片不足');next.shards-=cost;next.revision++;return {next,cost}}
function batch(state){let next=validate(state),ids=[];for(const n of [...nodes].sort((a,b)=>a.depth-b.depth||a.branch-b.branch)){if(n.type==='key'||next.unlocked.includes(n.id)||n.requires&&!next.unlocked.includes(n.requires)||n.cost>next.shards)continue;next=quote(next,[n.id]).next;ids.push(n.id)}return ids}
function purchase(storage,expected,ids){const current=load(storage);if(JSON.stringify(current)!==JSON.stringify(validate(expected)))throw Error('養成資料已更新，請重新確認');const {next}=quote(current,ids);storage.setItem(key,JSON.stringify(next));return next}
function firstClearReward(stage){if(!Number.isInteger(stage)||stage<1||stage>20)throw Error('無效關卡');return stage<=5?30:stage<=10?50:stage<=15?70:stage<20?100:220}
function claimVictory(storage,stage,result,now=Date.now()){if(result!=='我方勝利')throw Error('勝利才能取得首通獎勵');const amount=firstClearReward(stage),state=load(storage);if(state.firstClears.includes(stage))return {amount:0,state};if(stage>1&&!state.firstClears.includes(stage-1))throw Error('請先完成前一關');state.shards+=amount;if(!Number.isSafeInteger(state.shards))throw Error('材料餘額超出範圍');state.firstClears.push(stage);if(stage===1)state.idle={since:timestamp(now)};state.revision++;storage.setItem(key,JSON.stringify(state));return {amount,state}}

const idleHour=3600000,idleCap=12*idleHour;
function timestamp(now){if(!Number.isSafeInteger(now)||now<0)throw Error('時間資料無效');return now}
function validateIdle(idle){if(idle===undefined)return {};if(!idle||!Number.isSafeInteger(idle.since)||idle.since<0)throw Error('放置資料無效');return {idle:{since:idle.since}}}
function ensureIdle(storage,now=Date.now()){timestamp(now);const state=load(storage);if(state.firstClears.includes(1)&&!state.idle){state.idle={since:now};state.revision++;storage.setItem(key,JSON.stringify(state))}return state}
function idleStatus(state,now=Date.now()){validate(state);timestamp(now);const unlocked=state.firstClears.includes(1)&&!!state.idle;const elapsed=unlocked?Math.min(idleCap,Math.max(0,now-state.idle.since)):0;return {unlocked,amount:Math.floor(elapsed/idleHour)*5,elapsed,capped:elapsed===idleCap,nextIn:idleHour-elapsed%idleHour}}
function claimIdle(storage,now=Date.now()){const state=ensureIdle(storage,now),status=idleStatus(state,now);if(!status.amount)return {amount:0,state};state.shards+=status.amount;if(!Number.isSafeInteger(state.shards))throw Error('材料餘額超出範圍');state.idle.since=now-(status.capped?0:status.elapsed%idleHour);state.revision++;storage.setItem(key,JSON.stringify(state));return {amount:status.amount,state}}

function bonuses(state){validate(state);const result={attack:0,hp:0,armor:0,keys:[],level:1+state.unlocked.length};for(const id of state.unlocked){const n=nodes.find(n=>n.id===id);if(n.type==='key')result.keys.push(n.key);else result[n.type]++}return result}
function apply(unit,state,rules){if(unit.variant!=='flame'||unit.growthApplied)throw Error('角色養成重複套用');const b=bonuses(state),ratio=unit.hp/unit.max;unit.dmg=rules.stats.sword.dmg*(1+b.attack*.02);unit.max=rules.stats.sword.hp*(1+b.hp*.03);unit.hp=unit.max*ratio;unit.armor=rules.stats.sword.armor+b.armor*.005;rules.applyGarnetNodes(unit,b.keys);unit.max=Math.round(unit.max);unit.hp=Math.round(unit.hp);unit.growthApplied=true;unit.level=b.level}
const api={forHero,ensureIdle,idleStatus,claimIdle,firstClearReward,claimVictory,nodes,branches,key,empty,validate,load,quote,batch,purchase,bonuses,apply};if(typeof module!=='undefined')module.exports=api;else root.Starboard=api;
})(globalThis);
